<?php
require __DIR__.'/includes/bootstrap.php';
$q=trim($_GET['q']??'');$type=$_GET['type']??'all';$page=max(1,(int)($_GET['page']??1));$perPage=12;$rows=[];$total=0;
if($pdo&&$q){$like='%'.$q.'%';$where="status='published' AND (title LIKE ? OR content LIKE ? OR excerpt LIKE ?)";$params=[$like,$like,$like];if($type==='audio'){$where="status='published' AND (title LIKE ? OR description LIKE ?)";$params=[$like,$like];$count=$pdo->prepare("SELECT COUNT(*) FROM audio_tracks WHERE $where");$count->execute($params);$total=(int)$count->fetchColumn();$s=$pdo->prepare("SELECT title,slug,description AS excerpt,'Audio' AS content_type FROM audio_tracks WHERE $where ORDER BY created_at DESC LIMIT $perPage OFFSET ".(($page-1)*$perPage));$s->execute($params);$rows=$s->fetchAll();}else{$count=$pdo->prepare("SELECT COUNT(*) FROM articles WHERE $where");$count->execute($params);$total=(int)$count->fetchColumn();$s=$pdo->prepare("SELECT title,slug,excerpt,'Article' AS content_type FROM articles WHERE $where ORDER BY published_at DESC LIMIT $perPage OFFSET ".(($page-1)*$perPage));$s->execute($params);$rows=$s->fetchAll();}}
$title='Search';require __DIR__.'/includes/header.php';
?><div class="container"><h1>Search</h1><form class="search" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search sounds, triggers, guides or equipment..." required><select name="type"><option value="all" <?=$type==='all'?'selected':''?>>Articles</option><option value="audio" <?=$type==='audio'?'selected':''?>>Audio</option></select><button>Search</button></form><?php if($q):?><p class="muted"><?=e((string)$total)?> result(s) found.</p><div class="grid"><?php foreach($rows as $a):?><a class="card" href="<?=url($type==='audio'?'audio/'.$a['slug'].'/':$a['slug'].'/')?>"><small class="eyebrow"><?=e($a['content_type'])?></small><h3><?=e($a['title'])?></h3><p class="muted"><?=e($a['excerpt']??'')?></p></a><?php endforeach;?></div><?php if(!$rows):?><p class="muted">No results found. Try another keyword such as rain, whispering, or sleep.</p><?php endif;?><?php if($total>$perPage):?><nav aria-label="Search pages"><?php for($i=1;$i<=ceil($total/$perPage);$i++):?><a href="?q=<?=rawurlencode($q)?>&type=<?=rawurlencode($type)?>&page=<?=$i?>" <?=$i===$page?'aria-current="page"':''?>><?=$i?></a> <?php endfor;?></nav><?php endif;?><?php endif;?></div><?php require __DIR__.'/includes/footer.php';
